// Conformance: the Rust/WebAssembly core reproduces the declared corpus.
//
// The browser engine is an independent implementation, not the Python engine. The corpus
// in `fixtures/quantum_conformance.json` is generated by
// `scripts/export_web_conformance.py` from a dense NumPy reference, and this test replays
// exactly the same operations - same matrices, same qubit order, same control mask -
// through the WebAssembly core.
//
// Amplitudes are compared, not only probabilities: a uniform distribution hides a phase
// error, and a wrong imaginary part is exactly the kind of defect an independent
// implementation is supposed to catch.
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";

import { Core } from "../src/core";
import type { Mat2 } from "../src/circuit";

interface CorpusOp {
  target: number;
  ctrl: number;
  m: number[];
}

interface CorpusCase {
  name: string;
  qubits: number;
  ops: CorpusOp[];
  probabilities: number[];
  amplitudes: number[][];
}

interface Corpus {
  schema: string;
  tolerance: number;
  cases: CorpusCase[];
}

const corpus: Corpus = JSON.parse(
  readFileSync(new URL("./fixtures/quantum_conformance.json", import.meta.url), "utf8"),
);
const wasmBytes = readFileSync(new URL("../public/cqhecs_core.wasm", import.meta.url));

test("the corpus declares the schema and the qubit order", () => {
  assert.equal(corpus.schema, "hcs.web.conformance.v1");
  assert.ok(corpus.tolerance > 0 && corpus.tolerance < 1e-9, "a useful tolerance is below 1e-9");
  assert.ok(corpus.cases.length >= 5, "the corpus needs several independent cases");
});

for (const entry of corpus.cases) {
  test(`conformance: ${entry.name}`, async () => {
    const core = await Core.load(wasmBytes);
    assert.ok(core.init(entry.qubits), `the core refused ${entry.qubits} qubits`);
    for (const op of entry.ops) core.apply(op.target, op.ctrl, op.m as Mat2);

    const probabilities = core.probabilities();
    assert.equal(probabilities.length, 1 << entry.qubits);
    for (let index = 0; index < probabilities.length; index += 1) {
      const expected = entry.probabilities[index];
      const actual = probabilities[index];
      assert.ok(
        Math.abs(actual - expected) <= corpus.tolerance,
        `${entry.name}: P(${index}) = ${actual}, expected ${expected}`,
      );
    }

    // Normalisation is part of the contract, and a drifting norm is the first symptom of
    // a badly applied matrix.
    assert.ok(Math.abs(core.norm() - 1) <= 1e-12, `${entry.name}: state norm drifted to ${core.norm()}`);

    const amplitudes = core.amplitudes();
    for (let index = 0; index < entry.amplitudes.length; index += 1) {
      const [re, im] = entry.amplitudes[index];
      assert.ok(Math.abs(amplitudes[2 * index] - re) <= 1e-12, `${entry.name}: Re(${index})`);
      assert.ok(Math.abs(amplitudes[2 * index + 1] - im) <= 1e-12, `${entry.name}: Im(${index})`);
    }
    core.free();
  });
}

test("a deliberately wrong matrix is not accepted", async () => {
  // Guard against a vacuous corpus: if the comparison could not fail, every case above
  // would pass for the wrong reason.
  const entry = corpus.cases.find((candidate) => candidate.name === "bell");
  assert.ok(entry, "the corpus lost its Bell case");
  const core = await Core.load(wasmBytes);
  assert.ok(core.init(entry.qubits));
  const wrong = [...corpus.cases[0].ops[1].m];
  wrong[4] = 0; // break the lower-left entry of the X matrix
  core.apply(entry.ops[0].target, entry.ops[0].ctrl, entry.ops[0].m as Mat2);
  core.apply(entry.ops[1].target, entry.ops[1].ctrl, wrong as Mat2);
  const probabilities = core.probabilities();
  const matches = probabilities.every(
    (value, index) => Math.abs(value - entry.probabilities[index]) <= corpus.tolerance,
  );
  assert.equal(matches, false, "a broken matrix must not reproduce the reference");
  core.free();
});
